Given the tail of a circular linked list and an integer key, insert a new node with the given key at the end of the circular linked list.Examples:Input: key = 5, Output: 1 -> 7 -> 8 -> 10 -> 5Explanation: After inserting 5 at the end of the given circular linked list, it has elements as 1, 7, 8, 10, 5. Input: key = 1, Output: 2 -> 5 -> 7 -> 8 -> 10 -> 1Explanation: After inserting 1 at the end of the given circular linked list, it has elements as 2, 5, 7, 8, 10, 1. Try It YourselfInsertion at the End in Circular Linked List - O(1) Time and O(1) SpaceThe idea is to create a new node and insert it immediately after the current tail of the circular linked list. If the list is empty, make the new node point to itself and return it as the tail. Otherwise, link the new node to the current head (tail->next), update the current tail's next pointer to the new node, and return the new node as the updated tail. This inserts the node at the end while maintaining the circular nature of the linked list.Step-by-step approach:Create a new node with the given key.If the circular linked list is empty (tail == nullptr), make newNode->next point to itself and return newNode as the tail.Otherwise, set newNode->next to tail->next (the current head).Update tail->next to newNode.Return newNode as the new tail.
            C++

    #include <bits/stdc++.h>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;

    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

Node *insertAtEnd(Node *tail, int key)
{

    // Create a new node with the given key.
    Node *newNode = new Node(key);

    // If the circular linked list is empty,
    // make the new node point to itself.
    if (tail == nullptr)
    {
        newNode->next = newNode;
        return newNode;
    }

    // Insert the new node after the tail
    // and before the current head.
    newNode->next = tail->next;
    tail->next = newNode;

    // The newly inserted node becomes the new tail.
    return newNode;
}

// Function to print the circular linked list
void printList(Node *tail)
{
    if (tail == nullptr)
    {
        cout << "Empty";
        return;
    }

    Node *curr = tail->next;

    do
    {
        cout << curr->data;
        curr = curr->next;

        if (curr != tail->next)
            cout << "->";

    } while (curr != tail->next);
}

int main()
{

    // Create the circular linked list: 2 -> 5 -> 7 -> 8 -> 10
    Node *tail = new Node(10);
    tail->next = new Node(2);
    tail->next->next = new Node(5);
    tail->next->next->next = new Node(7);
    tail->next->next->next->next = new Node(8);
    tail->next->next->next->next->next = tail;

    int key = 1;

    tail = insertAtEnd(tail, key);

    printList(tail);

    return 0;
}


